RSpec.describe Timekeeping::EntryLookup do
  let(:owner_lookup_company) { create(:company) }
  let(:owner_lookup_admin) { create(:user, current_workspace_id: owner_lookup_company.id) }
  let(:owner_lookup_colleague) { create(:user, current_workspace_id: owner_lookup_company.id) }
  let(:owner_lookup_project) do
    create(:project, billable: true, client: create(:client, company: owner_lookup_company))
  end
  let(:owner_lookup_context) do
    Timekeeping::WriteContext.new(company: owner_lookup_company, actor: owner_lookup_admin, actor_kind: "user",
                                  request_id: "req-owner-lookup")
  end
  let(:owner_lookup_unused_client) do
    Class.new do
      define_method(:show_entry) { |**| raise "this branch must not call Timekeeping" }
    end.new
  end
  let(:owner_lookup_unused_local_owner) { Timekeeping::FakeLocalOwner.new }

  before do
    create(:employment, company: owner_lookup_company, user: owner_lookup_admin)
    owner_lookup_admin.add_role :admin, owner_lookup_company
    create(:employment, company: owner_lookup_company, user: owner_lookup_colleague)
    owner_lookup_colleague.add_role :employee, owner_lookup_company
  end

  def owner_lookup_find(ownership:, entry_id:, local_owner: owner_lookup_unused_local_owner,
                        read_client: owner_lookup_unused_client, scope: :company)
    described_class.find(ownership:, context: owner_lookup_context, entry_id:, local_owner:, read_client:, scope:)
  end

  def owner_lookup_row(id:, user_id:)
    {
      "id" => id, "company_id" => owner_lookup_company.id, "version" => 3, "project_id" => owner_lookup_project.id,
      "user_id" => user_id, "work_date" => Date.current.iso8601, "duration" => 90.0, "note" => "Owner copy",
      "bill_status" => "unbilled", "review_status" => "not_required", "source" => "manual", "source_metadata" => {},
      "agent_id" => nil, "proof_url" => nil, "proof_metadata" => nil, "locked" => false
    }
  end

  context "when the legacy store owns the entries" do
    it "finds a kept entry of the company without calling another store" do
      entry = create(:timesheet_entry, user: owner_lookup_colleague, project: owner_lookup_project, work_date: Date.current)

      found = owner_lookup_find(ownership: TimekeepingOwnership.current, entry_id: entry.id)

      expect(found.entry).to eq(entry)
      expect(found.version).to be_nil
      expect(owner_lookup_unused_local_owner.calls).to be_empty
    end

    it "raises RecordNotFound for a discarded entry" do
      entry = create(:timesheet_entry, user: owner_lookup_colleague, project: owner_lookup_project, work_date: Date.current)
      entry.discard!

      expect { owner_lookup_find(ownership: TimekeepingOwnership.current, entry_id: entry.id) }
        .to raise_error(ActiveRecord::RecordNotFound)
    end

    it "hides a colleague's entry under the actor scope" do
      entry = create(:timesheet_entry, user: owner_lookup_colleague, project: owner_lookup_project, work_date: Date.current)

      expect { owner_lookup_find(ownership: TimekeepingOwnership.current, entry_id: entry.id, scope: :actor) }
        .to raise_error(ActiveRecord::RecordNotFound)
    end
  end

  context "when Timekeeping owns the entries" do
    let(:owner_lookup_ownership) do
      TimekeepingOwnership.current.tap { |ownership| ownership.update!(owner: "timekeeping", generation: 2) }
    end
    let(:owner_lookup_recording_client) do
      row = owner_lookup_row(id: 5151, user_id: owner_lookup_colleague.id)
      Class.new do
        attr_reader :calls

        define_method(:show_entry) do |**kwargs|
          (@calls ||= []) << kwargs
          row
        end
      end.new
    end

    it "hydrates a colleague's entry for an admin with the row's own user and version" do
      found = owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 5151, read_client: owner_lookup_recording_client)

      expect(found.entry).to have_attributes(id: 5151, user_id: owner_lookup_colleague.id, note: "Owner copy")
      expect(found.entry).not_to be_persisted
      expect(found.entry.project).to eq(owner_lookup_project)
      expect(found.version).to eq(3)
      expect(TimesheetEntry.where(id: 5151)).not_to exist
    end

    it "asks Timekeeping for the entry as the actor, carrying the context's request id" do
      owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 5151, read_client: owner_lookup_recording_client)

      expect(owner_lookup_recording_client.calls).to eq([
        { company_id: owner_lookup_company.id, entry_id: 5151, acting_user_id: owner_lookup_admin.id,
          request_id: "req-owner-lookup" }
      ])
    end

    it "hides a colleague's entry under the actor scope" do
      expect do
        owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 5151, read_client: owner_lookup_recording_client,
                          scope: :actor)
      end.to raise_error(ActiveRecord::RecordNotFound)
    end

    def owner_lookup_client_answering(row)
      Class.new { define_method(:show_entry) { |**| row } }.new
    end

    it "raises RecordNotFound when the answer is a same-company entry with another id" do
      client = owner_lookup_client_answering(owner_lookup_row(id: 5152, user_id: owner_lookup_colleague.id))

      expect { owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 5151, read_client: client) }
        .to raise_error(ActiveRecord::RecordNotFound)
    end

    it "raises RecordNotFound when the answer names this company but another company's project" do
      foreign_project = create(:project, billable: true, client: create(:client, company: create(:company)))
      row = owner_lookup_row(id: 5151, user_id: owner_lookup_colleague.id).merge("project_id" => foreign_project.id)

      expect do
        owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 5151, read_client: owner_lookup_client_answering(row))
      end.to raise_error(ActiveRecord::RecordNotFound)
    end

    it "refuses an answer with no valid version, so no write can go out without If-Match" do
      [nil, "3", -1].each do |version|
        row = owner_lookup_row(id: 5151, user_id: owner_lookup_colleague.id).merge("version" => version)

        expect do
          owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 5151,
                            read_client: owner_lookup_client_answering(row))
        end.to raise_error(Timekeeping::EntryWriteClient::Error)
      end
    end
  end

  context "when the prepared monolith owns the entries" do
    let(:owner_lookup_ownership) do
      TimekeepingOwnership.current.tap { |ownership| ownership.update!(monolith_store: "prepared", generation: 3) }
    end

    it "asks only the local owner" do
      entry = TimesheetEntry.new(id: 6161, company_id: owner_lookup_company.id, user_id: owner_lookup_colleague.id,
                                 project: owner_lookup_project)
      local_owner = Timekeeping::FakeLocalOwner.new(entries: { 6161 => entry })

      found = owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 6161, local_owner:)

      expect(found.entry).to eq(entry)
      expect(local_owner.calls).to eq([{ method: :find_entry, kwargs: { context: owner_lookup_context, entry_id: 6161 } }])
    end

    it "raises RecordNotFound when the local owner answers another company's entry" do
      entry = TimesheetEntry.new(id: 6162, company_id: create(:company).id, user_id: owner_lookup_colleague.id)
      local_owner = Timekeeping::FakeLocalOwner.new(entries: { 6162 => entry })

      expect { owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 6162, local_owner:) }
        .to raise_error(ActiveRecord::RecordNotFound)
    end

    it "raises RecordNotFound when the local owner answers an entry with another id" do
      entry = TimesheetEntry.new(id: 6163, company_id: owner_lookup_company.id, user_id: owner_lookup_colleague.id,
                                 project: owner_lookup_project)
      local_owner = Timekeeping::FakeLocalOwner.new(entries: { 6161 => entry })

      expect { owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 6161, local_owner:) }
        .to raise_error(ActiveRecord::RecordNotFound)
    end

    it "refuses as ownership moving with the default local owner" do
      expect do
        owner_lookup_find(ownership: owner_lookup_ownership, entry_id: 6161,
                          local_owner: Timekeeping::Gateway::UnavailableLocalOwner.new)
      end.to raise_error(Timekeeping::Gateway::OwnershipMoving)
    end
  end
end

# Generated by Descant: acceptance tests below.
RSpec.describe Timekeeping::EntryLookup, "replayed delete answers" do
  let(:replayed_company) { create(:company) }
  let(:replayed_other_company) { create(:company) }
  let(:replayed_employee) { create(:user, current_workspace_id: replayed_company.id) }
  let(:replayed_colleague) { create(:user, current_workspace_id: replayed_company.id) }
  let(:replayed_project) { create(:project, billable: true, client: create(:client, company: replayed_company)) }
  let(:replayed_context) do
    Timekeeping::WriteContext.new(company: replayed_company, actor: replayed_employee, actor_kind: "user",
                                  request_id: "req-replayed-1")
  end

  before do
    create(:employment, company: replayed_company, user: replayed_employee)
    create(:employment, company: replayed_company, user: replayed_colleague)
    replayed_employee.add_role :employee, replayed_company
    replayed_colleague.add_role :employee, replayed_company
  end

  def replayed_row(**overrides)
    {
      "id" => 4242, "company_id" => replayed_company.id, "version" => 2, "project_id" => replayed_project.id,
      "user_id" => replayed_employee.id, "work_date" => Date.current.iso8601, "duration" => 60.0, "note" => "Gone",
      "bill_status" => "unbilled", "review_status" => "not_required", "source" => "manual", "source_metadata" => {},
      "agent_id" => nil, "proof_url" => nil, "proof_metadata" => nil, "locked" => false
    }.merge(overrides.transform_keys(&:to_s))
  end

  # "Replaying it needs a separate design that keeps the lookup-then-authorize order, and nothing is deleted twice meanwhile."
  it "refuses a replayed delete answer for another id, another company or an entry outside the actor scope as not found" do
    refused = [
      [replayed_row(id: 9999), :company],
      [replayed_row(company_id: replayed_other_company.id), :company],
      [replayed_row(user_id: replayed_colleague.id), :actor]
    ]

    refused.each do |row, scope|
      expect do
        described_class.replayed(context: replayed_context, row:, entry_id: 4242, scope:)
      end.to raise_error(ActiveRecord::RecordNotFound)
    end

    entry = described_class.replayed(context: replayed_context, row: replayed_row, entry_id: 4242, scope: :actor)
    expect(entry).to be_a(TimesheetEntry)
    expect([entry.id, entry.user_id, entry.project_id]).to eq([4242, replayed_employee.id, replayed_project.id])
  end

  it "accepts the matching replayed delete answer for this company under the company scope" do
    entry = described_class.replayed(context: replayed_context, row: replayed_row, entry_id: 4242, scope: :company)

    expect(entry).to be_a(TimesheetEntry)
    expect([entry.id, entry.company_id]).to eq([4242, replayed_company.id])
  end
end
